<template>
  <main class="studio">
    <header class="toolbar">
      <button class="back" @click="router.push('/dashboard')">← 工作台</button><b>智能画图</b><span class="type">当前类型：{{ currentTypeName }}</span>
      <button :disabled="generationLocked" @click="newFile">新建</button><label class="upload" :class="{disabled:generationLocked}">上传TXT/MD/SQL<input :disabled="generationLocked" type="file" accept=".txt,.md,.sql,text/plain,text/markdown,application/sql" @change="upload" /></label>
      <select v-model="selectedTemplate" :disabled="generationLocked" @change="insertTemplate"><option value="">插入模板</option><option v-for="item in templates" :key="item.type" :value="item.type">{{ item.name }}</option></select>
      <button type="button" :disabled="generationLocked" @click="check(true)">检查格式</button><button type="button" class="primary" :disabled="generationLocked||previewLoading||!engineReady" @click="render">{{ previewLoading?'处理中……':'生成预览' }}</button><button :disabled="generationLocked" @click="save">保存项目</button>
    </header>
    <section class="workspace">
      <aside class="left">
        <div class="editor-panel"><header><span>ThesisDiagram DSL</span><small>{{ currentTypeName }}</small></header><div class="editor-wrap"><div ref="lineGutter" class="lines"><span v-for="n in lineCount" :key="n" :class="{bad:n===activeErrorLine}">{{ n }}</span></div><textarea ref="editor" v-model="dsl" :readonly="generationLocked" aria-label="ThesisDiagram DSL代码编辑器" wrap="off" spellcheck="false" @scroll="syncEditorScroll" @keydown.ctrl.s.prevent="save" @keydown.tab.prevent="insertTab" @input="markChanged" /></div></div>
        <div class="checks"><nav><button :class="{on:tab==='assistant'}" @click="tab='assistant'">绘图助手</button><button :class="{on:tab==='local'}" @click="tab='local'">格式检查</button></nav>
          <DrawAssistantPanel v-if="tab==='assistant'" v-model="assistantInput" :stage="assistantStage" :status-text="assistantStatusText" :loading="aiLoading" :can-send="Boolean(assistantInput.trim()||pendingSqlText)" :messages="messages" :quick-commands="quickCommands" :has-undo="undoDsl!==null" @send="sendAssistant" @stop="stopAssistant" @clear="clearChat" @undo="undoAi" @quick="assistantInput=$event" />
          <div v-else class="issues"><p v-if="!validation">尚未检查</p><p v-else-if="!validation.issues?.length" class="ok">✓ 格式检查通过</p><template v-for="i in validation?.issues" :key="`${i.line}-${i.code}`"><button class="issue" @click="goLine(i.line)"><span :class="i.severity">{{ i.severity }}</span><b>第{{ i.line || 1 }}行 · {{ i.code }}</b><small>{{ i.message }} {{ i.suggestion }}</small></button><button class="ask" @click="askAssistant(i)">询问绘图助手</button></template></div>
        </div>
      </aside>
      <section class="preview" @wheel.prevent="wheelZoom" @pointerdown="startPan" @pointermove="movePan" @pointerup="stopPan" @pointerleave="stopPan"><div v-if="previewLoading" class="preview-state"><span class="spinner"></span><b>{{ previewStatus }}</b></div><div v-else-if="previewError" class="preview-state error-box"><b>预览生成失败</b><span>{{ previewError }}</span></div><div v-else-if="!svg" class="empty">{{ previewStatus || '输入 ThesisDiagram DSL 后生成预览' }}<br><small>语言规范：ThesisDiagram DSL v1.6</small></div><div v-else class="canvas" :style="{transform:`translate(${pan.x}px,${pan.y}px) scale(${zoom})`}" @dblclick="fit" v-html="svg"></div>
        <footer><span class="result-status">{{ previewStatus }}</span><button @click="fit">适应窗口</button><button @click="zoom=Math.min(3,zoom+.1)">＋</button><button @click="zoom=Math.max(.2,zoom-.1)">－</button><button @click="zoom=1">重置</button><span>{{ Math.round(zoom*100) }}%</span><button :disabled="!canDownload('svg')" @click="download('svg')">下载SVG</button><button :disabled="!canDownload('json')" @click="download('json')">下载JSON</button><button :disabled="!canDownload('png')" :title="artifactTitle('png')" @click="download('png')">下载PNG</button><button :disabled="!canDownload('vsdx')" :title="artifactTitle('vsdx')" @click="download('vsdx')">下载VSDX</button></footer>
      </section>
    </section>
  </main>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import DrawAssistantPanel from '../../components/diagram/DrawAssistantPanel.vue';
import { validateDiagram,renderDiagram,getDiagramHealth,streamDiagramAssistant,saveDiagramProject,exportDiagram,getDiagramPreview } from '../../api/rewrite'
const router=useRouter(), editor=ref(), lineGutter=ref(), dsl=ref(''), svg=ref(''), validation=ref(), aiResult=ref(), revisedDsl=ref(''), tab=ref('assistant'), busy=ref(false), previewLoading=ref(false), pngDownloading=ref(false), previewError=ref(''), previewDetails=ref(''), previewStatus=ref(''), exportsReady=ref({svg:false,png:false,json:false,vsdx:false}), engineReady=ref(true), requestSequence=ref(0), dirty=ref(false), zoom=ref(1), pan=ref({x:0,y:0}), drag=ref(null), dialog=ref(''), description=ref(''), selectedTemplate=ref(''), projectId=ref(null)
const previewId=ref(''), paidDsl=ref(''), artifactStates=ref({}), activeErrorLine=ref(0), assistantInput=ref(''), aiLoading=ref(false), aiController=ref(null), undoDsl=ref(null), conversationId=`diagram-${Date.now()}-${Math.random().toString(16).slice(2)}`
const generationLocked=ref(false), activeGeneration=ref(null), pendingSqlText=ref(''), aiStage=ref('正在理解图形需求'), assistantStage=ref('idle')
const messages=ref([{role:'assistant',text:'描述您要生成的图形，或告诉我如何修改当前DSL。AI修改代码免费，不会自动生成收费预览。'}])
const quickCommands=['生成完整代码','检查并修复','增加节点','删除节点','修改名称','调整关系','补全流程']
const templates=[{type:'function_module',name:'三级功能模块图',dsl:'@FunctionModule\n系统：论文管理系统\n模块：用户管理\n功能：注册、登录、权限管理'},{type:'flowchart',name:'标准程序流程图',dsl:'@Flowchart\n标题：业务流程\n[节点]\nN1|start|开始\nN2|process|处理业务\nN3|end|结束\n[连接]\nN1->N2\nN2->N3'},{type:'er_diagram',name:'Chen ER图',dsl:'@ERDiagram\n标题：用户订单ER图\n[实体]\n实体：用户|用户ID*，姓名\n实体：订单|订单ID*，金额\n[关系]\n关系：用户|订单|创建|1|n'},{type:'architecture',name:'系统架构图',dsl:'@ArchitectureDiagram\n标题：系统架构\n层：前端层\n组件：Web应用、移动端\n层：服务层\n组件：业务服务、认证服务'},{type:'use_case',name:'UML用例图',dsl:'@UseCaseDiagram\n标题：系统用例图\n[系统]\nS1|业务系统\n[参与者]\nA1|用户\n[用例]\nU1|S1|登录\n[关联]\nA1->U1\n[用例关系]'},{type:'block_diagram',name:'系统框图',dsl:'@BlockDiagram\n标题：系统框图\n[节点]\nI1|left|输入\nC1|center|处理器\nO1|right|输出\n[连接]\nI1->C1\nC1->O1'},{type:'sequence',name:'UML时序图',dsl:'@SequenceDiagram\n标题：登录时序图\n[参与者]\nA1|actor|用户\nP1|participant|系统\n[消息]\n1|A1->P1|请求登录'}]
const lineNumbers=computed(()=>Array.from({length:Math.max(1,dsl.value.split('\n').length)},(_,i)=>i+1).join('\n'))
const lineCount=computed(()=>Math.max(1,dsl.value.split('\n').length))
const headerNames={'@FunctionModule':'三级功能模块图','@Flowchart':'标准程序流程图','@ERDiagram':'Chen ER图','@ArchitectureDiagram':'系统架构图','@UseCaseDiagram':'UML用例图','@BlockDiagram':'系统框图','@SequenceDiagram':'UML时序图'}
function readHeader(source){const line=String(source||'').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n').map(x=>x.trim()).find(x=>x&&!x.startsWith('#')&&!x.startsWith('//'));if(!line)return {valid:false,empty:true,header:''};return {valid:Boolean(headerNames[line]),empty:false,header:line}}
const detectedHeader=computed(()=>readHeader(dsl.value)),currentTypeName=computed(()=>detectedHeader.value.empty?'等待识别':(headerNames[detectedHeader.value.header]||'不支持的图形类型'))
const stageLabels={idle:'等待输入',analyzing:'正在理解需求…',generating:'正在生成代码…',assembling:'代码已拼装，等待生成预览',rendering:'正在渲染图形…',success:'生成完成',error:'生成失败，请重试'}
const assistantStatusText=computed(()=>aiLoading.value?aiStage.value:(stageLabels[assistantStage.value]||stageLabels.idle))
function normalized(value){return String(value||'').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n').map(x=>x.replace(/\s+$/,'')).join('\n').replace(/\n+$/,'')}
function markChanged(){dirty.value=true;validation.value=null;previewError.value='';activeErrorLine.value=0;if(normalized(dsl.value)!==paidDsl.value){previewId.value='';artifactStates.value={}}if(svg.value)previewStatus.value='代码已修改，需要重新生成预览后才能下载'}
function newFile(){dsl.value='';svg.value='';validation.value=null;previewStatus.value='';exportsReady.value={svg:false,png:false,json:false,vsdx:false};projectId.value=null;previewId.value='';paidDsl.value='';artifactStates.value={};undoDsl.value=null;assistantStage.value='idle';tab.value='assistant';localStorage.removeItem('dropai_diagram_last_preview')} function insertTemplate(){const t=templates.find(x=>x.type===selectedTemplate.value);if(t){dsl.value=t.dsl;markChanged()}selectedTemplate.value=''}
async function check(forceTab=false){validation.value=await validateDiagram(dsl.value);const failed=!validation.value?.valid;if(forceTab||failed)tab.value='local';if(failed)activeErrorLine.value=validation.value?.issues?.[0]?.line||1;return validation.value}
async function render(){if(previewLoading.value)return;const source=dsl.value,seq=++requestSequence.value,controller=new AbortController();previewLoading.value=true;previewError.value='';previewStatus.value='正在检查格式……';try{const local=await check(false);if(!local?.valid){assistantStage.value='error';previewStatus.value='格式检查未通过';return}assistantStage.value='rendering';previewStatus.value='正在检查积分……';const r=await renderDiagram(projectId.value,source,controller.signal);if(seq!==requestSequence.value)return;projectId.value=r?.projectId||projectId.value;if(!r?.ok){assistantStage.value='error';if(r?.code==='DSL_INVALID'){validation.value=r.validation;tab.value='local'}else if(r?.code==='INSUFFICIENT_POINTS'){ElMessage.warning(r.message)}previewStatus.value=r?.message||'预览生成失败';return}previewStatus.value=r.reused?'正在加载历史预览……':'正在保存预览……';if(!r?.svg?.includes('<svg'))throw new Error('绘图接口没有返回有效SVG');svg.value=r.svg;previewId.value=r.previewId;paidDsl.value=normalized(source);artifactStates.value=r.artifacts||{};localStorage.setItem('dropai_diagram_last_preview',r.previewId);exportsReady.value={svg:artifactStates.value.svg==='READY',json:artifactStates.value.json==='READY',png:artifactStates.value.png==='READY',vsdx:artifactStates.value.vsdx==='READY'};dirty.value=false;fit();assistantStage.value='success';previewStatus.value=r.reused?'已加载该代码的历史预览，本次未重复扣费':'预览生成成功，已扣除10积分';ElMessage.success(previewStatus.value)}catch(error){if(seq!==requestSequence.value)return;assistantStage.value='error';previewError.value=error?.message||'生成预览失败';previewStatus.value='DSL格式正确，但绘图引擎执行失败';validation.value={valid:false,issues:[{line:1,severity:'error',code:'RENDER_ENGINE_FAILED',message:previewStatus.value,suggestion:previewError.value}]};tab.value='local'}finally{if(seq===requestSequence.value)previewLoading.value=false}}
function goLine(n){activeErrorLine.value=n||1;const e=editor.value,lines=dsl.value.split('\n');e.focus();e.setSelectionRange(lines.slice(0,n-1).join('\n').length+(n>1?1:0),lines.slice(0,n).join('\n').length)}
async function upload(e){const f=e.target.files?.[0];if(!f)return;if(f.size>1024*1024||!(/\.(txt|md|sql)$/i.test(f.name))){ElMessage.error('仅支持1MB以内TXT、MD或SQL');return}const bytes=await f.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(bytes);if((text.match(/�/g)||[]).length>2)text=new TextDecoder('gb18030').decode(bytes);text=text.replace(/^\uFEFF/,'').trim();if(/\.sql$/i.test(f.name)){pendingSqlText.value=text;assistantInput.value=`根据 ${f.name} 生成数据库ER图`;tab.value='assistant';ElMessage.success('SQL已安全读取，仅解析文本，不会执行或连接数据库')}else if(readHeader(text).valid){pendingSqlText.value='';dsl.value=text;markChanged();ElMessage.success('已打开 ThesisDiagram DSL 文件')}else{pendingSqlText.value='';assistantInput.value=text.slice(0,50000);tab.value='assistant';if(text.length>50000)ElMessage.warning('文字超过5万字，已截取前5万字');else ElMessage.success('文字已导入绘图助手，发送后将先压缩为100字内提纲再生成图形')}e.target.value=''}
async function save(){projectId.value=await saveDiagramProject({id:projectId.value,title:validation.value?.title||'未命名图形',dsl:dsl.value});dirty.value=false;ElMessage.success('项目已保存')}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function safeFileName(value){return String(value||'ThesisDiagram').replace(/[\\/:*?"<>|]/g,'_').trim()||'ThesisDiagram'}
function canDownload(format){return Boolean(previewId.value&&normalized(dsl.value)===paidDsl.value&&artifactStates.value?.[format]==='READY')}
function artifactTitle(format){if(artifactStates.value?.[format]==='UNAVAILABLE')return `${format.toUpperCase()}产物生成失败，请重新生成预览`;return canDownload(format)?'':`请先成功生成当前代码的预览`}
async function download(format){try{if(!canDownload(format))throw new Error(artifactTitle(format));saveBlob(await exportDiagram(previewId.value,format),`${safeFileName(validation.value?.title||'diagram')}.${format}`)}catch(error){ElMessage.error(error?.message||`${format.toUpperCase()}下载失败`)}} function fit(){zoom.value=1;pan.value={x:0,y:0}}
async function sha256(value){const bytes=new TextEncoder().encode(String(value||'').replace(/\r\n/g,'\n')),hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),x=>x.toString(16).padStart(2,'0')).join('')}
async function sendAssistant(){if(aiLoading.value||(!assistantInput.value.trim()&&!pendingSqlText.value))return;const instruction=assistantInput.value.trim()||'根据SQL生成数据库ER图',snapshot=dsl.value,sqlSnapshot=pendingSqlText.value,requestedDiagramType=sqlSnapshot?'ER_DIAGRAM':(readHeader(snapshot).header||''),requestId=crypto.randomUUID(),generationId=crypto.randomUUID(),baseDslHash=await sha256(snapshot);messages.value.push({role:'user',text:instruction.length>300?`${instruction.slice(0,300)}……（共${instruction.length}字）`:instruction});assistantInput.value='';undoDsl.value=snapshot;aiLoading.value=true;generationLocked.value=true;assistantStage.value='analyzing';aiStage.value='正在理解需求…';const controller=new AbortController();aiController.value=controller;activeGeneration.value={requestId,generationId,baseDslHash,snapshot};dsl.value='';validation.value=null;const stageNames={accepted:'正在理解需求…',analyzing:'正在理解需求…',summarizing:'正在提炼绘图需求…',summarized:'正在生成代码…',model_delta:'正在生成代码…',normalizing:'正在拼装代码…',compiling:'正在拼装代码…',validating:'正在检查图形代码…',heartbeat:'正在处理，请稍候…'},stageStates={accepted:'analyzing',analyzing:'analyzing',summarizing:'analyzing',summarized:'generating',model_delta:'generating',normalizing:'assembling',compiling:'assembling',validating:'assembling'};try{const r=await streamDiagramAssistant({requestId,generationId,conversationId,baseDslHash,diagramType:requestedDiagramType,instruction,currentDsl:snapshot,sqlText:sqlSnapshot},{signal:controller.signal,onEvent:(event)=>{if(activeGeneration.value?.requestId!==requestId)return;if(stageNames[event])aiStage.value=stageNames[event];if(stageStates[event])assistantStage.value=stageStates[event]}});if(activeGeneration.value?.requestId!==requestId||r.requestId!==requestId||r.generationId!==generationId)throw Object.assign(new Error('旧生成结果已丢弃，原图已恢复。'),{code:'STALE_GENERATION_RESULT'});assistantStage.value='assembling';dsl.value=r.dsl;pendingSqlText.value='';markChanged();validation.value={valid:true,issues:[],title:''};messages.value.push({role:'assistant',text:`代码已更新（首段${r.metrics?.firstByteMs||0}ms，总耗时${r.metrics?.modelTotalMs||0}ms，模型调用${r.metrics?.modelCalls||0}次），未生成收费预览。`});tab.value='assistant';ElMessage.success('DiagramIR已在本地编译为完整DSL')}catch(error){assistantStage.value=controller.signal.aborted?'idle':'error';dsl.value=snapshot;validation.value=null;markChanged();messages.value.push({role:'assistant',text:controller.signal.aborted?'本次生成已取消，原代码已恢复。':`${error.code||'GENERATION_FAILED'}：${error.message||'生成失败，原代码已恢复。'}`});ElMessage.error(controller.signal.aborted?'生成已取消，原代码已恢复。':(error.message||'生成失败，原代码已恢复。'))}finally{if(activeGeneration.value?.requestId===requestId)activeGeneration.value=null;aiLoading.value=false;generationLocked.value=false;aiController.value=null}}
function stopAssistant(){aiController.value?.abort()}
function clearChat(){messages.value=[{role:'assistant',text:'对话已清空，当前DSL不会改变。'}]}
function undoAi(){if(undoDsl.value===null)return;dsl.value=undoDsl.value;undoDsl.value=null;markChanged();check(false);ElMessage.success('已撤销上次AI修改')}
function askAssistant(issue){assistantInput.value=`请根据当前DSL修复错误：第${issue.line||1}行 ${issue.code}，${issue.message}。${issue.suggestion||''}`;tab.value='assistant'}
function insertTab(){const e=editor.value,start=e.selectionStart,end=e.selectionEnd;dsl.value=dsl.value.slice(0,start)+'  '+dsl.value.slice(end);requestAnimationFrame(()=>{e.selectionStart=e.selectionEnd=start+2});markChanged()}
function syncEditorScroll(event){if(lineGutter.value)lineGutter.value.scrollTop=event.currentTarget.scrollTop}
function wheelZoom(e){zoom.value=Math.min(3,Math.max(.2,zoom.value+(e.deltaY<0?.1:-.1)))} function startPan(e){if(!svg.value)return;drag.value={x:e.clientX-pan.value.x,y:e.clientY-pan.value.y};e.currentTarget.setPointerCapture?.(e.pointerId)} function movePan(e){if(drag.value)pan.value={x:e.clientX-drag.value.x,y:e.clientY-drag.value.y}} function stopPan(){drag.value=null}
onMounted(async()=>{try{const health=await getDiagramHealth();engineReady.value=Boolean(health?.ok);if(!engineReady.value)previewStatus.value='绘图引擎未就绪，请检查后端 diagram-worker 模块';const last=localStorage.getItem('dropai_diagram_last_preview');if(last){const r=await getDiagramPreview(last);dsl.value=r.dsl||'';svg.value=r.svg||'';previewId.value=r.previewId;projectId.value=r.projectId;paidDsl.value=normalized(dsl.value);artifactStates.value=r.artifacts||{};assistantStage.value=svg.value?'success':'idle';previewStatus.value='已恢复上次付费预览';validation.value=await validateDiagram(dsl.value)}}catch(error){if(!engineReady.value)return;localStorage.removeItem('dropai_diagram_last_preview')}})
onBeforeUnmount(()=>{activeGeneration.value=null;aiController.value?.abort()})
</script>

<style scoped>
